contam_genera = ['Ralstonia','Bradyrhizobium','Cutibacterium','Pelomonas','Delftia','Sphingomonas']
genus_map = tax['Genus'].fillna('')
present = {}
for g in contam_genera:
    asvs = genus_map[genus_map.str.contains(g, case=False, na=False)].index.tolist()
    if asvs:
        reads = counts[asvs].sum().sum()
        prevalence = (counts[asvs].sum(axis=1)>0).sum()
        present[g] = {"n_asvs": len(asvs), "total_reads": float(reads), "n_samples_present": int(prevalence)}
    else:
        present[g] = {"n_asvs":0}

# correlation of contaminant total relabund with depth (low biomass -> higher contam fraction expected)
contam_asvs = []
for g in contam_genera:
    contam_asvs += genus_map[genus_map.str.contains(g, case=False, na=False)].index.tolist()
if contam_asvs:
    contam_reads = counts[contam_asvs].sum(axis=1)
    contam_frac = contam_reads / counts.sum(axis=1)
    from scipy.stats import spearmanr
    r,p = spearmanr(meta['total_reads'], contam_frac)
